import { test } from 'node:test';
import assert from 'node:assert/strict';
import { dobrarValores, obterNomes } from './solution.mjs';

test('dobra todos os valores', () => {
  assert.deepEqual(dobrarValores([1, 2, 3]), [2, 4, 6]);
});

test('extrai os nomes dos objetos', () => {
  assert.deepEqual(obterNomes([{ nome: 'Ana' }, { nome: 'Beto' }]), ['Ana', 'Beto']);
});

test('lista vazia devolve lista vazia', () => {
  assert.deepEqual(dobrarValores([]), []);
});

test('recusa valor que não é lista', () => {
  assert.throws(() => obterNomes('abc'));
});

solutionCode:
export function dobrarValores(lista) {
  if (!Array.isArray(lista)) {
    throw new Error('lista precisa ser um array');
  }
  return lista.map((n) => n * 2);
}

export function obterNomes(lista) {
  if (!Array.isArray(lista)) {
    throw new Error('lista precisa ser um array');
  }
  return lista.map((item) => item.nome);
}
